@page "/apply"
@rendermode InteractiveServer
@using sv_74789a7ed3b0408cbf865394e9e3c019.Models
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="container py-4" style="max-width: 800px;">
    <h2 class="mb-4">Job Application</h2>

    @if (!_submitted)
    {
        <!-- Step Indicator -->
        <nav class="mb-4">
            <div class="d-flex justify-content-between position-relative">
                @for (int i = 0; i < _stepLabels.Length; i++)
                {
                    var step = i + 1;
                    var isCompleted = step < _currentStep;
                    var isCurrent = step == _currentStep;
                    var isFuture = step > _currentStep;

                    <div class="text-center flex-fill" style="z-index: 1;">
                        <button class="btn rounded-circle d-inline-flex align-items-center justify-content-center @(isCurrent ? "btn-primary" : isCompleted ? "btn-success" : "btn-secondary") @(isFuture ? "opacity-50" : "")"
                                style="width: 40px; height: 40px; font-size: 0.85rem;"
                                disabled="@isFuture"
                                @onclick="() => GoToStep(step)">
                            @if (isCompleted)
                            {
                                <span>✓</span>
                            }
                            else
                            {
                                <span>@step</span>
                            }
                        </button>
                        <div class="small mt-1 @(isFuture ? "text-muted" : isCurrent ? "fw-bold text-primary" : "text-success")">
                            @_stepLabels[i]
                        </div>
                    </div>
                }
            </div>
        </nav>

        @if (!string.IsNullOrEmpty(_errorMessage))
        {
            <div class="alert alert-danger alert-dismissible fade show" role="alert">
                @_errorMessage
                <button type="button" class="btn-close" @onclick="() => _errorMessage = null"></button>
            </div>
        }

        <!-- Step Content -->
        @switch (_currentStep)
        {
            case 1:
                <StepPersonalInfo FullName="@_fullName" Email="@_email" Phone="@_phone" Address="@_address"
                                  FullNameChanged="v => _fullName = v" EmailChanged="v => _email = v"
                                  PhoneChanged="v => _phone = v" AddressChanged="v => _address = v" />
                <div class="d-flex justify-content-end mt-3">
                    <button class="btn btn-primary" @onclick="NextFromPersonalInfo" disabled="@_isValidating">
                        @if (_isValidating)
                        {
                            <span class="spinner-border spinner-border-sm me-1"></span>
                            <span>Validating…</span>
                        }
                        else
                        {
                            <span>Next →</span>
                        }
                    </button>
                </div>
                break;

            case 2:
                <StepWorkHistory Entries="_workEntries" />
                <div class="d-flex justify-content-between mt-3">
                    <button class="btn btn-outline-secondary" @onclick="() => _currentStep = 1">← Back</button>
                    <button class="btn btn-primary" @onclick="NextFromWorkHistory">Next →</button>
                </div>
                break;

            case 3:
                <StepReferences References="_references" />
                <div class="d-flex justify-content-between mt-3">
                    <button class="btn btn-outline-secondary" @onclick="() => _currentStep = 2">← Back</button>
                    <button class="btn btn-primary" @onclick="NextFromReferences">Next →</button>
                </div>
                break;

            case 4:
                <StepCoverLetter CoverLetter="@_coverLetter" CoverLetterChanged="v => _coverLetter = v" />
                <div class="d-flex justify-content-between mt-3">
                    <button class="btn btn-outline-secondary" @onclick="() => _currentStep = 3">← Back</button>
                    <button class="btn btn-primary" @onclick="NextFromCoverLetter">Next →</button>
                </div>
                break;

            case 5:
                <StepReview FullName="@_fullName" Email="@_email" Phone="@_phone" Address="@_address"
                            WorkEntries="_workEntries" References="_references" CoverLetter="@_coverLetter"
                            OnEditStep="GoToStep" />
                <div class="d-flex justify-content-between mt-3">
                    <button class="btn btn-outline-secondary" @onclick="() => _currentStep = 4">← Back</button>
                    <button class="btn btn-success btn-lg" @onclick="SubmitApplication" disabled="@_isSubmitting">
                        @if (_isSubmitting)
                        {
                            <span class="spinner-border spinner-border-sm me-1"></span>
                            <span>Submitting…</span>
                        }
                        else
                        {
                            <span>Submit Application</span>
                        }
                    </button>
                </div>
                break;
        }
    }
    else
    {
        <!-- Confirmation -->
        <div class="text-center py-5">
            <div class="mb-3" style="font-size: 4rem;">✅</div>
            <h3 class="text-success">Application Submitted!</h3>
            <p class="lead mt-3">Your application has been received.</p>
            <p class="fs-4">Application ID: <strong>#@_applicationId</strong></p>
            <p class="text-muted">You will receive a confirmation email at <strong>@_email</strong>.</p>
        </div>
    }
</div>

@code {
    private static readonly string[] _stepLabels = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };

    private int _currentStep = 1;
    private bool _isValidating;
    private bool _isSubmitting;
    private bool _submitted;
    private int _applicationId;
    private string? _errorMessage;

    // Step 1
    private string _fullName = "";
    private string _email = "";
    private string _phone = "";
    private string _address = "";

    // Step 2
    private List<WorkEntryModel> _workEntries = new() { new WorkEntryModel() };

    // Step 3
    private List<ReferenceModel> _references = new() { new ReferenceModel(), new ReferenceModel() };

    // Step 4
    private string _coverLetter = "";

    private void GoToStep(int step)
    {
        if (step < _currentStep)
        {
            _errorMessage = null;
            _currentStep = step;
        }
    }

    private async Task NextFromPersonalInfo()
    {
        _errorMessage = null;

        if (string.IsNullOrWhiteSpace(_fullName) || string.IsNullOrWhiteSpace(_email)
            || string.IsNullOrWhiteSpace(_phone) || string.IsNullOrWhiteSpace(_address))
        {
            _errorMessage = "Please fill in all required fields.";
            return;
        }

        _isValidating = true;
        try
        {
            var isValid = await ApplicationService.ValidateEmailAsync(_email);
            if (!isValid)
            {
                _errorMessage = "Please enter a valid email address.";
                return;
            }
            _currentStep = 2;
        }
        finally
        {
            _isValidating = false;
        }
    }

    private void NextFromWorkHistory()
    {
        _errorMessage = null;
        foreach (var entry in _workEntries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title)
                || entry.StartDate == null || string.IsNullOrWhiteSpace(entry.Description))
            {
                _errorMessage = "Please complete all required fields for each work entry.";
                return;
            }
        }
        _currentStep = 3;
    }

    private void NextFromReferences()
    {
        _errorMessage = null;
        foreach (var r in _references)
        {
            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship)
                || string.IsNullOrWhiteSpace(r.Email) || string.IsNullOrWhiteSpace(r.Phone))
            {
                _errorMessage = "Please complete all fields for each reference.";
                return;
            }
        }
        _currentStep = 4;
    }

    private void NextFromCoverLetter()
    {
        _errorMessage = null;
        if (string.IsNullOrWhiteSpace(_coverLetter))
        {
            _errorMessage = "Please write a cover letter.";
            return;
        }
        _currentStep = 5;
    }

    private async Task SubmitApplication()
    {
        _isSubmitting = true;
        _errorMessage = null;

        try
        {
            var personal = new PersonalInfo(_fullName, _email, _phone, _address);
            var workHistory = new WorkHistory(_workEntries.Select(e =>
                new WorkEntry(e.Company!, e.Title!, e.StartDate!.Value, e.IsCurrent ? null : e.EndDate, e.Description!)).ToList());
            var references = _references.Select(r =>
                new Reference(r.Name!, r.Relationship!, r.Email!, r.Phone!)).ToList();

            var application = new JobApplication(personal, workHistory, references, _coverLetter);
            _applicationId = await ApplicationService.SubmitApplicationAsync(application);
            _submitted = true;
        }
        catch
        {
            _errorMessage = "An error occurred while submitting. Please try again.";
        }
        finally
        {
            _isSubmitting = false;
        }
    }

    public class WorkEntryModel
    {
        public string? Company { get; set; }
        public string? Title { get; set; }
        public DateTime? StartDate { get; set; }
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string? Description { get; set; }
    }

    public class ReferenceModel
    {
        public string? Name { get; set; }
        public string? Relationship { get; set; }
        public string? Email { get; set; }
        public string? Phone { get; set; }
    }
}

