+                    <button class="btn btn-outline-secondary" @onclick="() => _currentStep = 1">← Back</button>
+                    <button class="btn btn-primary" @onclick="NextFromWorkHistory">Next →</button>
+                </div>
+                break;
+
+            case 3:
+                <StepReferences References="_references" />
+                <div class="d-flex justify-content-between mt-3">
+                    <button class="btn btn-outline-secondary" @onclick="() => _currentStep = 2">← Back</button>
+                    <button class="btn btn-primary" @onclick="NextFromReferences">Next →</button>
+                </div>
+                break;
+
+            case 4:
+                <StepCoverLetter CoverLetter="@_coverLetter" CoverLetterChanged="v => _coverLetter = v" />
+                <div class="d-flex justify-content-between mt-3">
+                    <button class="btn btn-outline-secondary" @onclick="() => _currentStep = 3">← Back</button>
+                    <button class="btn btn-primary" @onclick="NextFromCoverLetter">Next →</button>
+                </div>
