@using static sv_74789a7ed3b0408cbf865394e9e3c019.Components.Pages.Apply

<h4 class="mb-3">Work History</h4>

@for (int i = 0; i < Entries.Count; i++)
{
    var index = i;
    var entry = Entries[index];

    <div class="card mb-3">
        <div class="card-body">
            <div class="d-flex justify-content-between align-items-center mb-2">
                <h6 class="card-title mb-0">Position @(index + 1)</h6>
                @if (Entries.Count > 1)
                {
                    <button class="btn btn-outline-danger btn-sm" @onclick="() => RemoveEntry(index)">Remove</button>
                }
            </div>

            <div class="row">
                <div class="col-md-6 mb-3">
                    <label class="form-label">Company <span class="text-danger">*</span></label>
                    <input type="text" class="form-control" @bind="entry.Company" placeholder="Company name" />
                </div>
                <div class="col-md-6 mb-3">
                    <label class="form-label">Job Title <span class="text-danger">*</span></label>
                    <input type="text" class="form-control" @bind="entry.Title" placeholder="Job title" />
                </div>
            </div>

            <div class="row">
                <div class="col-md-4 mb-3">
                    <label class="form-label">Start Date <span class="text-danger">*</span></label>
                    <input type="date" class="form-control" @bind="entry.StartDate" />
                </div>
                <div class="col-md-4 mb-3">
                    <label class="form-label">End Date</label>
                    <input type="date" class="form-control" @bind="entry.EndDate" disabled="@entry.IsCurrent" />
                </div>
                <div class="col-md-4 mb-3 d-flex align-items-end">
                    <div class="form-check">
                        <input type="checkbox" class="form-check-input" id="current-@index" @bind="entry.IsCurrent" />
                        <label class="form-check-label" for="current-@index">I currently work here</label>
                    </div>
                </div>
            </div>

            <div class="mb-2">
                <label class="form-label">Description <span class="text-danger">*</span></label>
                <textarea class="form-control" rows="3" @bind="entry.Description" placeholder="Describe your responsibilities and achievements"></textarea>
            </div>
        </div>
    </div>
}

<button class="btn btn-outline-primary" @onclick="AddEntry">
    + Add Another Position
</button>

@code {
    [Parameter] public List<WorkEntryModel> Entries { get; set; } = new();

    private void AddEntry()
    {
        Entries.Add(new WorkEntryModel());
    }

    private void RemoveEntry(int index)
    {
        if (Entries.Count > 1)
        {
            Entries.RemoveAt(index);
        }
    }
}

